import * as React from "react"
import { addPropertyControls, ControlType, RenderTarget } from "framer"

/**
 * NimbusSequencePlayer — scroll-driven image sequence, tuned for phones.
 *
 * Same mapping as the ImageSequence marketplace component (Trigger "Top":
 * frame = (scrollY - top - delay) / sectionHeight * count), but:
 *  - one <canvas>, drawn at most once per animation frame and only when the
 *    frame index changes (no React re-render of every frame on scroll);
 *  - frames are fetched up front (encoded, small) and decoded ahead of the
 *    scroll direction in a sliding window, so the next frames are ready
 *    before they are shown, without holding every decoded frame in memory.
 *
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 */
type Props = {
    frames: string
    sectionHeight: number
    startDelay: number
    decodeAhead: number
    smoothing: number
    style?: React.CSSProperties
}

export default function NimbusSequencePlayer(props: Props) {
    const { frames = "", sectionHeight = 1688, startDelay = 0, decodeAhead = 12, smoothing = 0.12, style } = props
    const urls = React.useMemo(
        () =>
            String(frames || "")
                .split(/[\s,]+/)
                .map((s) => s.trim())
                .filter((s) => /^https?:\/\//.test(s)),
        [frames]
    )
    const isCanvas = RenderTarget.current() === RenderTarget.canvas
    const wrapRef = React.useRef<HTMLDivElement | null>(null)
    const canvasRef = React.useRef<HTMLCanvasElement | null>(null)

    React.useEffect(() => {
        if (isCanvas || !urls.length) return
        const wrap = wrapRef.current
        const canvas = canvasRef.current
        if (!wrap || !canvas) return
        const ctx = canvas.getContext("2d", { alpha: true })
        if (!ctx) return

        let disposed = false
        const count = urls.length
        // Encoded bytes (small) for every frame, fetched a few at a time in order;
        // decoded bitmaps only near the playhead. Decoding from a Blob runs off the
        // main thread (decoding from an <img> blocks scrolling on Chrome/Android).
        const blobs: (Promise<Blob> | null)[] = new Array(count).fill(null)
        const ctrl = typeof AbortController !== "undefined" ? new AbortController() : null
        const getBlob = (i: number) => {
            if (!blobs[i]) {
                blobs[i] = fetch(urls[i], { signal: ctrl?.signal, cache: "force-cache" }).then((r) => {
                    if (!r.ok) throw new Error(String(r.status))
                    return r.blob()
                })
                blobs[i]!.catch(() => {
                    blobs[i] = null
                })
            }
            return blobs[i]!
        }
        // Download progress for the page loader (Asset Loading → Wait for Sequence).
        // Progress = all downloads + the first frames decoded and ready to draw,
        // so the first scroll after the loader never waits on a decode.
        let loaded = 0
        let warmTarget = 0 // set once the decode window is known
        const warmed = new Set<number>()
        const report = () => {
            const detail = { loaded: loaded + Math.min(warmed.size, warmTarget), total: count + warmTarget }
            ;(window as any).__nimbusSequenceProgress = detail
            window.dispatchEvent(new CustomEvent("botanika:sequence-progress", { detail }))
        }
        report()
        ;(async () => {
            let next = 0
            const worker = async () => {
                while (!disposed && next < count) {
                    const i = next++
                    try {
                        await getBlob(i)
                    } catch {}
                    if (disposed) return
                    loaded++ // failed frames count too, so the loader never hangs
                    report()
                }
            }
            await Promise.all([worker(), worker(), worker(), worker()])
        })()
        // WebKit (every iPhone browser) decodes createImageBitmap(blob) on the main
        // thread; HTMLImageElement.decode() is the async path there. It also has
        // less memory headroom on older iPhones, so keep a tighter window.
        const ua = typeof navigator !== "undefined" ? navigator.userAgent : ""
        const isWebKit =
            (window as any).__nspForceImg === true ||
            (/AppleWebKit/.test(ua) && !/Chrome|Chromium|Android|Edg\//.test(ua)) ||
            /iPhone|iPad|iPod/.test(ua) ||
            (navigator.platform === "MacIntel" && (navigator as any).maxTouchPoints > 1)
        const MAX_DECODING = isWebKit ? 2 : 3
        const ahead = isWebKit ? Math.min(decodeAhead, 12) : decodeAhead
        const keep = isWebKit ? ahead + Math.ceil(ahead / 3) + 2 : ahead * 2 + 4
        warmTarget = Math.min(count, ahead + 1)
        report()
        const objectUrls: string[] = []

        // Decode in Web Workers: the bitmap is built off the main thread in every
        // engine (incl. WebKit) and transferred back ready to draw.
        type Job = { done: (b: ImageBitmap | null) => void; fallback: () => void }
        const workerJobs = new Map<number, Job>()
        const workers: Worker[] = []
        let workerUrl = ""
        let workersOk = typeof Worker !== "undefined" && typeof createImageBitmap === "function"
        if (workersOk) {
            try {
                const src =
                    "self.onmessage=async(e)=>{const{i,blob}=e.data;try{const bm=await createImageBitmap(blob);self.postMessage({i,bm},[bm])}catch(err){self.postMessage({i,err:String(err)})}}"
                workerUrl = URL.createObjectURL(new Blob([src], { type: "text/javascript" }))
                for (let k = 0; k < 2; k++) {
                    const w = new Worker(workerUrl)
                    w.onmessage = (e: MessageEvent) => {
                        const { i, bm, err } = e.data || {}
                        const job = workerJobs.get(i)
                        workerJobs.delete(i)
                        if (!job) return bm?.close?.()
                        if (bm) job.done(bm)
                        else {
                            workersOk = false // e.g. no createImageBitmap in workers: use the main-thread path
                            job.fallback()
                        }
                    }
                    w.onerror = () => {
                        workersOk = false
                        const jobs = [...workerJobs.values()]
                        workerJobs.clear()
                        jobs.forEach((j) => j.fallback())
                    }
                    workers.push(w)
                }
            } catch {
                workersOk = false
            }
        }
        let rr = 0
        const nextWorker = () => (workersOk && workers.length ? workers[rr++ % workers.length] : null)
        const bitmaps = new Map<number, ImageBitmap | HTMLImageElement>()
        const pending = new Set<number>()
        // The component may be fixed (top 0) or in flow; measure its document top once.
        const rect0 = wrap.getBoundingClientRect()
        const fixed = getComputedStyle(wrap).position === "fixed" || wrap.closest("[style*='position: fixed']")
        const top = fixed ? 0 : rect0.top + window.scrollY

        // Scroll position as a fractional frame (smoothed below).
        const targetFor = () => {
            const y = (window.scrollY || 0) - top - startDelay
            return Math.max(0, Math.min(count - 1, (y / Math.max(1, sectionHeight)) * count))
        }
        let cur = targetFor()
        let lastT = 0
        const indexFor = () => Math.max(0, Math.min(count - 1, Math.round(cur)))

        const decode = (i: number) => {
            if (i < 0 || i >= count || bitmaps.has(i) || pending.has(i) || disposed) return
            if (pending.size >= MAX_DECODING) return // retried from the next frame()
            pending.add(i)
            const done = (b: ImageBitmap | HTMLImageElement | null) => {
                pending.delete(i)
                if (disposed) {
                    ;(b as any)?.close?.()
                    return
                }
                if (b) bitmaps.set(i, b)
                if (i >= warmStart && i < warmStart + warmTarget && !warmed.has(i)) {
                    warmed.add(i) // failed decodes count too, so the loader never hangs
                    report()
                }
                schedule() // draw if wanted, and start the next queued decode
            }
            const viaImg = (src: string) => {
                const im = new Image()
                im.crossOrigin = "anonymous"
                im.decoding = "async"
                im.src = src
                im.decode().then(() => done(im), () => done(null))
            }
            const onMain = (blob: Blob) => {
                if (!isWebKit && typeof createImageBitmap === "function") {
                    createImageBitmap(blob).then(done, () => viaImg(urls[i]))
                } else {
                    if (!objectUrls[i]) objectUrls[i] = URL.createObjectURL(blob)
                    viaImg(objectUrls[i])
                }
            }
            getBlob(i).then(
                (blob) => {
                    const w = nextWorker()
                    if (!w) return onMain(blob)
                    workerJobs.set(i, { done, fallback: () => onMain(blob) })
                    w.postMessage({ i, blob })
                },
                () => viaImg(urls[i])
            )
        }

        let want = indexFor()
        const warmStart = Math.max(0, Math.min(want, count - warmTarget)) // frames the loader waits for
        let raf = 0
        const schedule = () => {
            if (!raf) raf = requestAnimationFrame(frame)
        }
        let drawn = -1
        let lastIndex = want
        let dir = 1
        let cw = 0
        let ch = 0

        const evict = () => {
            for (const [k, b] of bitmaps) {
                if (Math.abs(k - want) > keep) {
                    ;(b as any).close?.()
                    bitmaps.delete(k)
                }
            }
        }
        const warm = () => {
            decode(want)
            for (let d = 1; d <= ahead; d++) {
                decode(want + d * dir) // ahead first
            }
            for (let d = 1; d <= Math.ceil(ahead / 3); d++) decode(want - d * dir)
            evict()
        }

        const resize = () => {
            const r = wrap.getBoundingClientRect()
            const dpr = Math.min(window.devicePixelRatio || 1, 2)
            const w = Math.max(1, Math.round(r.width * dpr))
            const h = Math.max(1, Math.round(r.height * dpr))
            if (w !== cw || h !== ch) {
                cw = w
                ch = h
                canvas.width = w
                canvas.height = h
                drawn = -1
            }
        }

        const nearestReady = (i: number) => {
            if (bitmaps.has(i)) return i
            for (let d = 1; d < 8; d++) {
                if (bitmaps.has(i - d * dir)) return i - d * dir
                if (bitmaps.has(i + d * dir)) return i + d * dir
            }
            return -1
        }

        const frame = (now: number) => {
            raf = 0
            if (disposed) return
            // Ease the playhead toward the scroll position (frame-rate independent),
            // so touch flicks and jumpy scroll still play every frame smoothly.
            const target = targetFor()
            const dt = lastT ? Math.min(0.1, (now - lastT) / 1000) : 1 / 60
            lastT = now
            if (smoothing > 0) {
                cur += (target - cur) * (1 - Math.exp(-dt / smoothing))
                if (Math.abs(target - cur) < 0.02) cur = target
            } else cur = target
            if (cur !== target) schedule()
            else lastT = 0
            want = indexFor()
            if (want !== lastIndex) {
                dir = want > lastIndex ? 1 : -1
                lastIndex = want
            }
            warm()
            resize()
            const i = nearestReady(want)
            if (i < 0 || i === drawn) return
            const img = bitmaps.get(i) as any
            const iw = img.width || img.naturalWidth
            const ih = img.height || img.naturalHeight
            // object-fit: cover, centred (same framing as the captured viewport)
            const s = Math.max(cw / iw, ch / ih)
            const dw = iw * s
            const dh = ih * s
            ctx.clearRect(0, 0, cw, ch)
            ctx.drawImage(img, (cw - dw) / 2, (ch - dh) / 2, dw, dh)
            drawn = i
        }

        window.addEventListener("scroll", schedule, { passive: true })
        window.addEventListener("resize", schedule)
        schedule()
        return () => {
            disposed = true
            ctrl?.abort()
            for (const u of objectUrls) if (u) URL.revokeObjectURL(u)
            for (const w of workers) w.terminate()
            if (workerUrl) URL.revokeObjectURL(workerUrl)
            workerJobs.clear()
            if (raf) cancelAnimationFrame(raf)
            window.removeEventListener("scroll", schedule)
            window.removeEventListener("resize", schedule)
            for (const [, b] of bitmaps) (b as any).close?.()
            bitmaps.clear()
        }
    }, [urls, sectionHeight, startDelay, decodeAhead, smoothing, isCanvas])

    if (isCanvas) {
        return (
            <div
                style={{
                    ...style,
                    background: urls[0] ? `center / cover no-repeat url(${urls[0]})` : "rgba(136,85,255,0.1)",
                    display: "flex",
                    alignItems: "flex-end",
                    justifyContent: "center",
                    color: "rgba(255,255,255,0.7)",
                    fontSize: 11,
                }}
            >
                {urls.length ? `${urls.length} frames` : "Paste frame URLs"}
            </div>
        )
    }
    return (
        <div ref={wrapRef} style={{ ...style, position: "relative", width: "100%", height: "100%", pointerEvents: "none" }}>
            <canvas
                ref={canvasRef}
                aria-hidden="true"
                style={{ position: "absolute", inset: 0, width: "100%", height: "100%", display: "block" }}
            />
        </div>
    )
}

addPropertyControls(NimbusSequencePlayer, {
    frames: { type: ControlType.String, title: "Frames", displayTextArea: true, defaultValue: "", placeholder: "Frame URLs, one per line, in order" },
    sectionHeight: { type: ControlType.Number, title: "Section Height", defaultValue: 1688, min: 100, step: 10 },
    startDelay: { type: ControlType.Number, title: "Start Delay", defaultValue: 0, min: 0, step: 10 },
    decodeAhead: { type: ControlType.Number, title: "Decode Ahead", defaultValue: 12, min: 2, max: 40, step: 1 },
    smoothing: { type: ControlType.Number, title: "Smoothing", defaultValue: 0.12, min: 0, max: 0.6, step: 0.01, unit: "s", description: "0 = theo sát scroll; lớn hơn = trôi mượt hơn" },
})
